		{
			SIM_Science objItem = new SIM_Science();
			if (!Convert.IsDBNull(reader[C_SCIENCEID])) objItem.ScienceID = Convert.ToString(reader[C_SCIENCEID]);
			if (!Convert.IsDBNull(reader[C_SCIENCENAME])) objItem.ScienceName = Convert.ToString(reader[C_SCIENCENAME]);
            if (!Convert.IsDBNull(reader[C_Manager])) objItem.Manager = Convert.ToString(reader[C_Manager]);
            if (!Convert.IsDBNull(reader[C_HEADTEACHERID])) objItem.HeadTeacherID = Convert.ToString(reader[C_HEADTEACHERID]);
