			if (!Convert.IsDBNull(reader[C_CREATEDAT])) objItem.CreatedAt = Convert.ToDateTime(reader[C_CREATEDAT]);
			if (!Convert.IsDBNull(reader[C_MODIFIEDBY])) objItem.ModifiedBy = Convert.ToString(reader[C_MODIFIEDBY]);
			if (!Convert.IsDBNull(reader[C_MODIFIEDAT])) objItem.ModifiedAt = Convert.ToDateTime(reader[C_MODIFIEDAT]);
