			if (!Convert.IsDBNull(drw[C_CREATEDBY])) objItem.CreatedBy = Convert.ToString(drw[C_CREATEDBY]);
			if (!Convert.IsDBNull(drw[C_CREATEDAT])) objItem.CreatedAt = Convert.ToDateTime(drw[C_CREATEDAT]);
			if (!Convert.IsDBNull(drw[C_MODIFIEDBY])) objItem.ModifiedBy = Convert.ToString(drw[C_MODIFIEDBY]);
			if (!Convert.IsDBNull(drw[C_MODIFIEDAT])) objItem.ModifiedAt = Convert.ToDateTime(drw[C_MODIFIEDAT]);
			return objItem;
		}

